site_demand_characterization.characterization_source:
use tsr_ast::Node;
use tsr_checker::{Checker, check::FileContext};
use tsr_core::Arena;

#[derive(Debug, PartialEq, Eq)]
struct Output { baked: String, own: Option<String>, other: Option<String> }
#[derive(Debug)]
struct Observation { label: String, first: Option<String>, rounds: Vec<Vec<Output>>, diagnostics: Vec<String> }

fn observe(label: &str, source: &str, first: Option<&str>) -> Observation {
    let arena = Arena::new();
    let parsed = tsr_parser::parse(&arena, source);
    assert!(parsed.diagnostics.is_empty());
    let root = Node::SourceFile(parsed.source_file).node_id().unwrap();
    let bound = tsr_binder::bind(&arena, parsed.source_file, &parsed.nodes,
        tsr_binder::FileInfo { name: "control.ts", text: source });
    let symbols = [bound.lookup_local(root, "value").unwrap(),
        bound.lookup_local(root, "copy").unwrap()];
    let sites = symbols.map(|symbol| bound.symbols().get(symbol).declarations[0]);
    let mut checker = Checker::new(&bound, &parsed.nodes, &parsed.node_map);
    checker.set_strict_null_checks(true);
    checker.set_no_implicit_any(true);
    if let Some(name) = first { checker.get_type_of_symbol(bound.lookup_local(root, name).unwrap()); }
    let mut rounds = Vec::new();
    for reverse in [false, true, false] {
        let order = if reverse { [1, 0] } else { [0, 1] };
        let mut outputs = [None, None];
        for i in order {
            let id = checker.get_type_of_symbol(symbols[i]);
            let baked = checker.type_to_string(id);
            let own = checker.type_to_string_at(id, sites[i]);
            let other = checker.type_to_string_at(id, sites[1-i]);
            assert_eq!(checker.get_type_of_symbol(symbols[i]), id,
                "presentation changed completed symbol identity: {label}");
            outputs[i] = Some(Output { baked, own, other });
        }
        rounds.push(outputs.into_iter().map(Option::unwrap).collect());
    }
    checker.check_source_file(root, FileContext { ambient: false, has_parse_errors: false });
    let diagnostics = checker.diagnostics().iter().map(|d| d.1.text()).collect();
    Observation { label: label.to_owned(), first: first.map(str::to_owned), rounds, diagnostics }
}

#[test]
fn original_and_spread_site_reads_characterize_cold_and_warm_orders() {
    let mut rows = Vec::new();
    for &(label, source) in FIXTURES {
        for first in [None, Some("value"), Some("copy")] { rows.push(observe(label, source, first)); }
    }
    println!("SITE_DEMAND_RECORD={rows:#?}");
    for row in &rows {
        assert_eq!(row.rounds[0], row.rounds[1], "warm reversed changed: {}, {:?}", row.label, row.first);
        assert_eq!(row.rounds[0], row.rounds[2], "warm repeat changed: {}, {:?}", row.label, row.first);
    }
    for chunk in rows.chunks_exact(3) {
        assert_eq!(chunk[0].rounds, chunk[1].rounds, "object-first changed: {}", chunk[0].label);
        assert_eq!(chunk[0].rounds, chunk[2].rounds, "spread-first changed: {}", chunk[0].label);
        assert_eq!(chunk[0].diagnostics, chunk[1].diagnostics);
        assert_eq!(chunk[0].diagnostics, chunk[2].diagnostics);
    }
}
const FIXTURES: &[(&str, &str)] = &[
    ("source_order", "const value = { b: \"s\", a: 1 }; const copy = { ...value, a: \"x\" };"),
    ("nested", "const value = { inner: { n: 1 } }; const copy = { ...value };"),
    ("written_quote", "const value = { label: 'held' as const }; const copy = { ...value };"),
    ("readonly", "const value = { n: 1, label: \"held\" } as const; const copy = { ...value };"),
    ("accessor", "const value = { get n() { return 1; } }; const copy = { ...value };"),
    ("method_this", "const value = { n: 1, read() { return this.n; } }; const copy = { ...value };"),
    ("generic_alias", "type Box<T> = { item: T }; const item: Box<number> = { item: 1 }; const value = { item }; const copy = { ...value };"),
    ("qualified", "namespace Names { export interface Item { n: number; } } const item: Names.Item = { n: 1 }; const value = { item }; const copy = { ...value };"),
    ("computed", "declare const key: unique symbol; const value = { [key]: 1, [\"label\"]: \"s\" }; const copy = { ...value };"),
    ("optional", "const item: { n?: number } = {}; const value = { item }; const copy = { ...value };"),
    ("mapped", "type Box<T> = { [K in keyof T]: T[K] }; const item: Box<{ n: number }> = { n: 1 }; const value = { item }; const copy = { ...value };"),
    ("recursive_return", "const value = { next() { return value; } }; const copy = { ...value };"),
];

